function resize(file,max,cb){const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const k=Math.min(1,max/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);cb(c.toDataURL('image/jpeg',.8))};i.src=r.result};r.readAsDataURL(file)}
function pp(id,amt){const t=(k,v)=>k+String(v.length).padStart(2,'0')+v;id=id.replace(/\D/g,'');const acc=id.length>=13?t('02',id):t('01','0066'+id.slice(1));
let s=t('00','01')+t('01','12')+t('29',t('00','A000000677010111')+acc)+t('53','764')+t('54',amt.toFixed(2))+t('58','TH')+'6304',c=0xFFFF;
for(const ch of s){c^=ch.charCodeAt(0)<<8;for(let i=0;i<8;i++)c=c&0x8000?((c<<1)^0x1021)&0xFFFF:(c<<1)&0xFFFF}return s+c.toString(16).toUpperCase().padStart(4,'0')}
