function pager(n,p,js,s=PS){const c=Math.ceil(n/s);if(c<2)return'';let b='';for(let i=0;i<c;i++)b+=`<button class="${i===p?'on':''}" onclick="${js.replace('#',i)}">${i+1}</button>`;return`<div class="pg">${b}<span class="mu">${n} รายการ</span></div>`}
const DT={};
function dt(id,rows,cols,o={}){const s=DT[id]=Object.assign(DT[id]||{q:'',k:-1,d:1,p:0,fv:''},{rows,cols,o});post.push(()=>drawDT(id));
return`<div class="box"><div class="row"><input placeholder="🔍 ค้นหา" value="${esc(s.q)}" oninput="DT['${id}'].q=this.value;DT['${id}'].p=0;drawDT('${id}')" style="max-width:260px">${o.fk?`<select style="width:auto" onchange="DT['${id}'].fv=this.value;DT['${id}'].p=0;drawDT('${id}')"><option value="">ทั้งหมด</option>${o.fo.map(x=>`<option ${s.fv===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:''}</div><div id="dt-${id}" style="overflow-x:auto"></div></div>`}
function drawDT(id){const s=DT[id],el=$('#dt-'+id);if(!el)return;const q=s.q.toLowerCase();
let l=s.rows.filter(r=>(!s.fv||s.o.fk(r)===s.fv)&&(!q||s.cols.map(c=>c.t(r)).join(' ').toLowerCase().includes(q)));
if(s.k>=0){const t=s.cols[s.k].t;l.sort((a,b)=>(t(a)>t(b)?1:t(a)<t(b)?-1:0)*s.d)}
s.p=Math.min(s.p,Math.max(0,Math.ceil(l.length/PS)-1));
el.innerHTML=`<table class="dt"><tr>${s.cols.map((c,i)=>`<th onclick="sortDT('${id}',${i})">${c.h}${s.k===i?(s.d>0?' ▲':' ▼'):''}</th>`).join('')}</tr>${l.slice(s.p*PS,s.p*PS+PS).map(r=>`<tr>${s.cols.map(c=>`<td>${c.f?c.f(r):esc(c.t(r))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${s.cols.length}" class="mu">ไม่พบข้อมูล</td></tr>`}</table>${pager(l.length,s.p,`DT['${id}'].p=#;drawDT('${id}')`)}`}
function sortDT(id,i){const s=DT[id];s.d=s.k===i?-s.d:1;s.k=i;drawDT(id)}
