if(!chk('rerr',[[n.length<2,'ชื่ออย่างน้อย 2 ตัวอักษร'],[!EM.test(e),'รูปแบบอีเมลไม่ถูกต้อง'],[db.users.some(u=>u.email===e),'อีเมลนี้ถูกใช้แล้ว'],[!PH.test(p),'เบอร์โทรต้องเป็นตัวเลข 10 หลักขึ้นต้นด้วย 0'],[w.length<6,'รหัสผ่านอย่างน้อย 6 ตัวอักษร'],[w!==$('#rc').value,'รหัสผ่านไม่ตรงกัน']]))return;
