if(!chk('perr',[[n.length<2,'ชื่ออย่างน้อย 2 ตัวอักษร'],[p&&!PH.test(p),'เบอร์โทรต้องเป็นตัวเลข 10 หลัก'],[pw&&pw.length<6,'รหัสผ่านใหม่อย่างน้อย 6 ตัวอักษร'],[a&&val('ps').length<2,'กรอกคณะ/สถาบัน'],[a&&val('pb').length>300,'แนะนำตัวไม่เกิน 300 ตัวอักษร']]))return;
